begin;
truncate public.couples,public.profiles,public.operation_receipts cascade;
set local search_path=public,extensions;select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-000000000084','retention@example.test',now());
insert into public.profiles(user_id,display_name) values('00000000-0000-4000-8000-000000000084','Permanent');
insert into public.couples(id,name,start_date) values('10000000-0000-4000-8000-000000000084','Permanent','2024-01-01');
insert into public.memberships(couple_id,user_id,slot) values('10000000-0000-4000-8000-000000000084','00000000-0000-4000-8000-000000000084',1);
insert into public.memories(couple_id,creator_id,title,event_date,created_at) values('10000000-0000-4000-8000-000000000084','00000000-0000-4000-8000-000000000084','Old memory','2020-01-01','2020-01-01');
insert into public.entries(couple_id,author_id,kind,title,content,event_date,created_at) values('10000000-0000-4000-8000-000000000084','00000000-0000-4000-8000-000000000084','letter','Old letter','Keep','2020-01-01','2020-01-01');
insert into public.photos(couple_id,uploader_id,storage_path,event_date,bytes,format,width,height,created_at) values('10000000-0000-4000-8000-000000000084','00000000-0000-4000-8000-000000000084','retention/ready.jpg','2020-01-01',100,'image/jpeg',24,16,'2020-01-01');
insert into public.operation_receipts values('00000000-0000-4000-8000-000000000084',gen_random_uuid(),'test','h','{}',now()-interval '25 hours',now()-interval '1 hour'),('00000000-0000-4000-8000-000000000084',gen_random_uuid(),'test','h','{}',now()-interval '1 hour',now()+interval '23 hours');
insert into public.change_events(couple_id,actor_id,operation_id,category,action,created_at) values('10000000-0000-4000-8000-000000000084','00000000-0000-4000-8000-000000000084',gen_random_uuid(),'memory','create',now()-interval '91 days');
insert into public.upload_batches(couple_id,owner_id,state,closed_at,created_at) values('10000000-0000-4000-8000-000000000084','00000000-0000-4000-8000-000000000084','closed',now()-interval '91 days',now()-interval '92 days');
select public.notification_maintenance();
select is((select count(*)::integer from public.change_events),0,'Operational events expire after 90 days');
select is((select count(*)::integer from public.upload_batches),0,'Clean closed batches expire');
select is((select count(*)::integer from public.operation_receipts),1,'Receipt survives expiry plus 24 hours');
select is((select count(*)::integer from public.memories),1,'Old memory preserved');
select is((select count(*)::integer from public.entries),1,'Old letter preserved');
select is((select count(*)::integer from public.photos where state='ready'),1,'Ready photo preserved');
select is((select count(*)::integer from public.profiles),1,'Saved profile preserved');
select is((select count(*)::integer from public.couples),1,'Shared settings preserved');
select is(private.capacity_state(349999999)->>'db_warning','false','No warning below 350 MB');
select is(private.capacity_state(350000000)->>'db_warning','true','Warning begins at 350 MB');
select is(private.capacity_state(399999999)->>'growth_blocked','false','Growth allowed below 400 MB');
select is(private.capacity_state(400000000)->>'growth_blocked','true','Nonessential growth stops at 400 MB');
select * from finish();rollback;
